    {"id": "TC3", "title": "Test cancelling a shipped order", "type": "negative", "preconditions": "The order has been shipped and the order status is 'Shipped'.", "steps": ["Go to the order history page.", "Select the order to be cancelled.", "Click the 'Cancel' button."], "expected_result": "The order status does not change and no cancellation email is sent to the customer.", "covers": ["AC2"]},
