    {"id": "TC5", "title": "Test cancelling an order that has been cancelled more than 24 hours ago", "type": "boundary", "preconditions": "The order was placed within the last 24 hours and the order status is 'Placed'.", "steps": ["Go to the order history page.", "Select the order to be cancelled.", "Click the 'Cancel' button."], "expected_result": "The order status changes to 'Cancelled' and a cancellation email is sent to the customer.", "covers": ["AC1", "AC3", "AC4"]},
    {"id": "TC6", "title": "Test cancelling an order that has been cancelled more than 24 hours ago", "type": "boundary", "preconditions": "The order was placed more than 24 hours ago and the order status is 'Placed'.", "steps": ["Go to the order history page.", "Select the order to be cancelled.", "Click the 'Cancel' button."], "expected_result": "The order status does not change and no cancellation email is sent to the customer.", "covers": ["AC1"]},
    {"id": "TC7", "title": "Test cancelling an order that has been shipped more than 24 hours ago", "type": "boundary", "preconditions": "The order has been shipped more than 24 hours ago and the order status is 'Shipped'.", "steps": ["Go to the order history page.", "Select the order to be cancelled.", "Click the 'Cancel' button."], "expected_result": "The order status does not change and no cancellation email is sent to the customer.", "covers": ["AC2"]}
