    {"id": "TC5", "title": "Test cancelling an order and verifying the email", "type": "positive", "preconditions": "The order status is 'Placed' and it was placed within the last 24 hours.", "steps": ["Go to the order history page.", "Select an order that was placed within the last 24 hours.", "Click the 'Cancel' button for the selected order.", "Verify a cancellation email is sent to the customer."], "expected_result": "A cancellation email is sent to the customer.", "covers": ["AC1", "AC4"]},
    {"id": "TC6", "title": "Test cancelling an order that has already been cancelled", "type": "negative", "preconditions": "The order status is 'Cancelled' and it was placed within the last 24 hours.", "steps": ["Go to the order history page.", "Select an order that has already been cancelled.", "Attempt to click the 'Cancel' button for the selected order."], "expected_result": "An error message is displayed indicating that the order cannot be cancelled because it has already been cancelled.", "covers": ["AC1"]},
